-- risen_extended: a mod converted from the archives of another mod (generated by risen-pack2mod or tools/extmod_gen.py). Generic code; every number is in data/*.lua.
--
--   stage 1  new item templates (risen.template.create, clone of the closest shipped item) and their extra properties
--   stage 2  changes of shipped items (risen.balance items section)
--   stage 3  recipes: edits of the new recipe items, new recipe items for pearls / gold / ore (shipped items cannot become recipes at run time)
--   stage 4  other template edits (monster actors, light range)
-- Applied on the first `tick` (templates) and on every `session.start` (again, now with the live entities, because a world keeps its own copies).
-- Every entry is applied on its own: one bad entry is logged and counted, the rest still applies.
local cfg = require("config")
local ITEMS = require("data.items")
local NEW = require("data.new_items")
local REC = require("data.recipes")
local PATCH = require("data.patches")
local log = risen.log

local M = { passes = {}, failed = {} }   -- M.passes[when] = { new_items = n, ... }; M.failed = { "stage name: reason" }

local function sorted(t)
    local keys = {}
    for k in pairs(t) do keys[#keys + 1] = k end
    table.sort(keys)
    return keys
end

local function fail(first, stage, name, why)
    local msg = ("%s %s: %s"):format(stage, name, tostring(why))
    if first then
        M.failed[#M.failed + 1] = msg
        log.warn("risen_extended: " .. msg)
    end
end

local function apply_properties(name, props, instances, first, stage)
    local ok_n = 0
    for _, set in ipairs(sorted(props)) do
        for _, p in ipairs(sorted(props[set])) do
            local ok, err = risen.template.patch(name, { [set] = { [p] = props[set][p] } }, { instances = instances })
            if ok then ok_n = ok_n + 1 else fail(first, stage .. " property", name .. "." .. set .. "." .. p, err) end
        end
    end
    return ok_n
end

local CREATE_KEYS = { "value", "damage", "mana_cost", "requires", "modifies", "use_type", "category", "mesh", "icon", "material" }

local function stage_new_items(instances, first, counts)
    for _, name in ipairs(sorted(NEW)) do
        local e = NEW[name]
        local over = {}
        for _, k in ipairs(CREATE_KEYS) do over[k] = e[k] end
        local t, why = risen.template.create(name, e.base, over, { instances = instances })
        if not t and (e.mesh or e.icon) and (tostring(why):find("mesh") or tostring(why):find("icon")) then
            -- a mesh or icon name the layer cannot resolve (yet): create it anyway, it only fails to show
            over.check_assets = false
            t, why = risen.template.create(name, e.base, over, { instances = instances })
            if t and first then log.warn(("risen_extended: %s: created with unchecked asset names (%s)"):format(name, tostring(why))) end
        end
        if t then
            counts.new_items = (counts.new_items or 0) + 1
            if e.properties then counts.new_item_props = (counts.new_item_props or 0) + apply_properties(name, e.properties, instances, first, "new item") end
        else
            fail(first, "new item", name, why)
        end
    end
end

local function stage_items(instances, first, counts)
    for _, name in ipairs(sorted(ITEMS)) do
        local e = ITEMS[name]
        local entry = {}
        for k, v in pairs(e) do if k ~= "properties" then entry[k] = v end end
        entry.properties = e.properties
        local report, why = risen.balance.apply({ items = { [name] = entry } }, { instances = instances })
        if not report or not report.ok then
            -- retry without the free-form properties, then one by one, so a single bad property costs only itself
            entry.properties = nil
            local r2, why2 = true, nil
            if next(entry) ~= nil then r2, why2 = risen.balance.apply({ items = { [name] = entry } }, { instances = instances }) end
            if not r2 then fail(first, "item", name, why2 or why)
            else
                counts.items = (counts.items or 0) + 1
                counts.item_props = (counts.item_props or 0) + apply_properties(name, e.properties or {}, instances, first, "item")
            end
        else
            counts.items = (counts.items or 0) + 1
            if e.properties then counts.item_props = (counts.item_props or 0) + 1 end
        end
    end
end

local function stage_recipes(instances, first, counts)
    for _, name in ipairs(sorted(REC.edit)) do
        local report, why = risen.balance.apply({ recipes = { [name] = REC.edit[name] } }, { instances = instances })
        if report and report.ok then counts.recipes = (counts.recipes or 0) + 1 else fail(first, "recipe", name, why) end
    end
    for _, name in ipairs(sorted(REC.new)) do
        local e = {}
        for k, v in pairs(REC.new[name]) do if k ~= "from" then e[k] = v end end
        e.learn = nil   -- given by this mod's own start handler below (cfg.learn_recipes)
        local report, why = risen.balance.apply({ new_recipes = { [name] = e } }, { instances = instances })
        if report and report.ok then counts.new_recipes = (counts.new_recipes or 0) + 1 else fail(first, "new recipe", name, why) end
    end
end

local function stage_patches(instances, first, counts)
    for _, name in ipairs(sorted(PATCH)) do
        local ok, err = risen.template.patch(name, PATCH[name], { instances = instances })
        if ok then counts.patches = (counts.patches or 0) + 1 else fail(first, "patch", name, err) end
    end
end

local function on(flag) return cfg[flag] ~= false end   -- every feature group is on unless config.lua says false

local function apply(when, instances, first)
    local counts = {}
    if on("new_items") then stage_new_items(instances, first, counts) end
    if on("balance") then stage_items(instances, first, counts) end
    if on("new_items") then stage_recipes(instances, first, counts) end
    if on("balance") then stage_patches(instances, first, counts) end
    M.passes[#M.passes + 1] = { when = when, counts = counts }
    local parts = {}
    for _, k in ipairs(sorted(counts)) do parts[#parts + 1] = k .. "=" .. counts[k] end
    log.info(("risen_extended: %s: %s; %d problem(s) so far"):format(when, table.concat(parts, " "), #M.failed))
end

local first = true
risen.on("tick", function()
    if not first then return end
    first = false
    apply("first tick", false, true)
end)
risen.on("session.start", function(mode)
    apply("session.start (" .. tostring(mode) .. ")", true, false)
end)

-- ---- dialogue edits (phase B): XP rewards and trader refills on shipped dialogue infos, once per process (the infos are in memory for the whole process) ----
local DLG = require("data.dialog")
local WORLD = require("data.world")

local function set_props(inf, idx, props)
    for k, v in pairs(props) do
        if not inf:set_command_property(idx, k, tostring(v)) then return false, k end
    end
    return true
end

-- property edits of a shipped info (the converter's `changes`, only with --classic): a value changed where the info still has the old one, a condition appended
local function apply_info_ops(inf, ops, bad)
    local n, appended = 0, {}
    for _, op in ipairs(ops) do
        local ok, why = false, nil
        if op.kind == "info" then
            if tostring(inf:get_property(op.name)) == op.old then ok = inf:set_property(op.name, op.new) else why = "it has another value" end
        elseif op.kind == "command" then
            if inf:get_command_property(op.index, op.name) == op.old then ok = inf:set_command_property(op.index, op.name, op.new) else why = "it has another value" end
        elseif op.kind == "condition" then
            if inf:get_condition_property(op.index, op.name) == op.old then ok = inf:set_condition_property(op.index, op.name, op.new) else why = "it has another value" end
        elseif op.kind == "add_condition" then
            local idx = appended[op.index]
            if not idx then
                idx = inf:add_condition(op.class)
                appended[op.index] = idx
            end
            ok = idx and inf:set_condition_property(idx, op.name, op.new)
        end
        if ok then n = n + 1 else bad(op, why) end
    end
    return n
end

local function stage_dialog()
    local c = { xp_added = 0, xp_changed = 0, trade_infos = 0, trade_entries = 0, ops = 0 }
    for _, ch in ipairs(DLG.changes or {}) do
        local inf = risen.dialog.get(ch.info)
        if not inf then fail(true, "dialogue edit", ch.info, "no such dialogue info")
        else
            c.ops = c.ops + apply_info_ops(inf, ch.ops, function(op, why) fail(true, "dialogue edit", ch.info .. " " .. op.kind .. " " .. op.name, why or "cannot be set") end)
        end
    end
    for _, e in ipairs(DLG.xp.add) do
        local inf = risen.dialog.get(e.info)
        if not inf then fail(true, "xp", e.info, "no such dialogue info")
        else
            local idx = inf:add_command("GiveXP")
            local ok = idx and set_props(inf, idx, { Amount = e.amount })
            if ok then c.xp_added = c.xp_added + 1 else fail(true, "xp", e.info, "cannot add GiveXP") end
        end
    end
    for _, e in ipairs(DLG.xp.change) do
        local inf = risen.dialog.get(e.info)
        local done = false
        if inf then
            for i = 1, inf:command_count() do
                if inf:get_command_property(i, "Amount") == tostring(e.old) then
                    done = inf:set_command_property(i, "Amount", tostring(e.new))
                    break
                end
            end
        end
        if done then c.xp_changed = c.xp_changed + 1 else fail(true, "xp change", e.info, "command not found") end
    end
    for _, t in ipairs(DLG.trade) do
        local inf = risen.dialog.get(t.info)
        if not inf then fail(true, "trade", t.info, "no such dialogue info")
        else
            c.trade_infos = c.trade_infos + 1
            for _, e in ipairs(t.entries) do
                local idx = inf:add_script_command()
                local ok = idx and inf:set_script(idx, "OnTradeInfo_RefillTradeItems")
                if ok then ok = set_props(inf, idx, { Self = e.trader, Other = e.item, OtherType = "gEOtherType_TemplateEntity", Param = e.count }) end
                if ok then c.trade_entries = c.trade_entries + 1 else fail(true, "trade", t.info .. " " .. e.trader .. " " .. e.item, "cannot add the RunScript command") end
            end
        end
    end
    M.dialog = c
    log.info(("risen_extended: dialogue: %d XP rewards, %d XP changes, %d trade entries on %d infos"):format(c.xp_added, c.xp_changed, c.trade_entries, c.trade_infos))
end

local dialog_done = false
risen.on("tick", function()
    if dialog_done then return end
    dialog_done = true
    if not on("dialogue") or not on("new_items") then return end
    local ok, err = pcall(stage_dialog)
    if not ok then fail(true, "dialogue", "stage", err) end
end)

-- the engine runs these infos at the chapter changes; the first chapter's stock is also handed out at the start of a new game (the traders sell it from the beginning)
local function refill(trader, item, n)
    local t = risen.entity.get(trader)
    local p = risen.entity.player()
    if not t or not p then return false end
    local x, y, z = p:position()
    local e = risen.entity.spawn(item, (x or 0) + 100, (y or 0) + 10, z or 0)
    if not e then return false end
    local ok = pcall(function() risen.script.call("OnTradeInfo_RefillTradeItems", t, e, n) end)
    e:kill()
    return ok
end

local function stage_stock()
    local n, bad = 0, 0
    for _, t in ipairs(DLG.trade) do
        if t.chapter == 1 then
            for _, e in ipairs(t.entries) do
                if refill(e.trader, e.item, e.count) then n = n + 1 else bad = bad + 1; fail(true, "stock", e.trader .. " " .. e.item, "refill failed") end
            end
        end
    end
    M.stock = { refilled = n, failed = bad }
    log.info(("risen_extended: chapter 1 trader stock: %d refills, %d failed"):format(n, bad))
end

-- ---- the world (phase B): items in containers, equipment of NPCs; once per savegame (game variable), on world.ready ----
local function stage_world()
    local c = { containers = 0, items = 0, equipped = 0 }
    for _, box in ipairs(WORLD.containers) do
        local e = risen.entity.by_id(box.id)
        if not e then fail(true, "container", box.name .. " " .. box.layer, "not found")
        else
            for _, it in ipairs(box.items) do
                if risen.item.give(e, it.item, it.count) >= 0 then c.items = c.items + 1 else fail(true, "container", box.name, "cannot give " .. it.item) end
            end
            c.containers = c.containers + 1
        end
    end
    for _, q in ipairs(WORLD.equipment) do
        local e = risen.entity.by_id(q.id)
        if not e then fail(true, "equipment", q.name, "not found")
        else
            risen.item.give(e, q.item, 1)
            if risen.item.equip(e, q.item) then c.equipped = c.equipped + 1 end
        end
    end
    M.world = c
    log.info(("risen_extended: world: %d containers (%d item stacks), %d NPC items equipped"):format(c.containers, c.items, c.equipped))
end

risen.on("world.ready", function(mode)
    if (risen.gamevar.get("RISEN_EXTENDED_WORLD") or 0) ~= 0 then return end
    if not on("world") and not on("dialogue") then return end
    risen.gamevar.set("RISEN_EXTENDED_WORLD", 1)
    if on("world") and on("new_items") then
        local ok, err = pcall(stage_world)
        if not ok then fail(true, "world", "stage", err) end
    end
    if mode == "new" and on("dialogue") and on("new_items") then
        local ok2, err2 = pcall(stage_stock)
        if not ok2 then fail(true, "stock", "stage", err2) end
    end
end)


-- ---- teacher limits (phase B): the teaching list of the placed NPC (saved with the entity; written on every world.ready, it is idempotent) ----
local function stage_teachers()
    local n, bad = 0, 0
    for _, t in ipairs(WORLD.teachers) do
        local e = risen.entity.by_id(t.id)
        local enum = risen.balance.skill_enum(t.skill)
        if e and enum then
            local ok, err = risen.npc.set_teach_limit(e, enum, t.max)
            if ok then n = n + 1 else bad = bad + 1; fail(true, "teacher", t.name, err) end
        else
            bad = bad + 1
            fail(true, "teacher", t.name, e and ("unknown skill " .. t.skill) or "not found")
        end
    end
    M.teachers = { set = n, failed = bad }
    log.info(("risen_extended: teacher limits: %d set, %d failed"):format(n, bad))
end

risen.on("world.ready", function()
    if not on("teachers") then return end
    local ok, err = pcall(stage_teachers)
    if not ok then fail(true, "teachers", "stage", err) end
end)

-- ---- the player's start: plans of the new recipe items, and (config.lua) a kit of the new items until the traders carry them ----
local function give_once(player, name, n)
    local var = "RISEN_EXTENDED_GIVEN_" .. name
    if (risen.gamevar.get(var) or 0) ~= 0 then return end
    risen.gamevar.set(var, 1)
    risen.item.give(player, name, n or 1)
end

risen.on("world.ready", function(mode)
    local player = risen.entity.player()
    if not player then return end
    for _, name in ipairs(sorted(REC.new)) do
        if cfg.learn_recipes and on("new_items") then
            local ok, err = pcall(function() risen.recipe.learn_once(player, name) end)
            if not ok then log.warn("risen_extended: learn " .. name .. ": " .. tostring(err)) end
        end
    end
    local kit = cfg.starter_kit
    if mode == "new" and kit and kit ~= "none" and on("new_items") then
        for _, name in ipairs(sorted(NEW)) do
            local skip = false
            if kit == "plans" and not name:find("_Recipe$") then skip = true end
            if cfg.skip_intermediate and (name:find("_Hot$") or name:find("_Shaped$") or name:find("_Dull$")) then skip = true end
            if not skip then give_once(player, name, 1) end
        end
        log.info("risen_extended: starter kit '" .. tostring(kit) .. "' handed out")
    end
end)

M.cfg = cfg
M.items, M.new, M.rec, M.patch = ITEMS, NEW, REC, PATCH
M.dlg, M.wrld = DLG, WORLD

-- the scenario (scripts/test-run.ps1 -WaitForResult -Param check=extmod) is part of the mod, loaded only in a test run
if risen.test and risen.test.is_active() and risen.test.param("check") == "extmod" then
    require("check")(M)
end
if risen.test and risen.test.is_active() and risen.test.param("check") == "extplay" then
    require("play")(M)
end
